def execute(arguments):
    """
    删除文件或目录

    参数:
        arguments (dict): 包含以下字段
            - path (str): 文件或目录路径，必填

    返回:
        dict: 包含删除结果的字典
            - success (bool): 是否成功
            - path (str): 删除的路径
            - type (str): "file" 或 "directory"
            - action (str): "deleted"
            - error (str): 错误信息（失败时）
    """
    import os
    import shutil

    path = arguments.get("path", "")

    if not path:
        return {"success": False, "error": "请提供文件路径"}

    if not os.path.exists(path):
        return {"success": False, "error": f"文件不存在: {path}"}

    try:
        if os.path.isfile(path):
            os.remove(path)
            return {"success": True, "path": path, "type": "file", "action": "deleted"}
        elif os.path.isdir(path):
            shutil.rmtree(path)
            return {"success": True, "path": path, "type": "directory", "action": "deleted"}
        else:
            return {"success": False, "error": "未知的文件类型"}
    except Exception as e:
        return {"success": False, "error": f"删除失败: {str(e)}"}
